/**
 * Build a compact, non-identifying calibration report from an existing eval cache.
 * Input is a private chesscom-evals file generated by calibrate-chesscom.mjs.
 * Output contains only aggregate scores and error stats (no games, players or PGNs).
 * This tool does not use external services.
 */
import { readFileSync, writeFileSync } from 'node:fs';
import { createRequire } from 'node:module';
const require = createRequire(import.meta.url);
const A=require('../www/accuracy.js'); const R=require('../www/review-classification.js');
const raw=JSON.parse(readFileSync(process.argv[2],'utf8'));
const output=process.argv[3];
const res=[];
for(const g of raw){
 const credit=g.best.map((b,i)=>R.openingBookPly(g.moves,i)?g.moves[i]:b);
 const score=A.scoreGame(g.pov,g.moves,credit);
 res.push({id:g.url.split('/').pop(),split:g.split,time_class:g.time_class,plies:g.moves.length,
   white:g.accuracy_white,black:g.accuracy_black,w:score.w,b:score.b});
}
function stats(samples) {
 const errors=samples.flatMap(x=>[x.w-x.white,x.b-x.black]);
 return {gameCount:samples.length,sampleCount:errors.length,
  mae: errors.length?errors.reduce((a,b)=>a+Math.abs(b),0)/errors.length:null,
  bias:errors.length?errors.reduce((a,b)=>a+b,0)/errors.length:null,
  rmse:errors.length?Math.sqrt(errors.reduce((a,b)=>a+b*b,0)/errors.length):null,
  max:errors.length?Math.max(...errors.map(Math.abs)):null};
}
const report={overall:stats(res),train:stats(res.filter(x=>x.split==='train')),
 test:stats(res.filter(x=>x.split==='test')),
 blitz:stats(res.filter(x=>x.time_class==='blitz')),
 rapid:stats(res.filter(x=>x.time_class==='rapid'))};
if(output) writeFileSync(output,JSON.stringify({report,rows:res},null,2));
console.log(JSON.stringify(report,null,2));
